#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SysPwrCmd {
    pub power_state: bool,
    pub rolling_counter: u8,
}

impl SysPwrCmd {
    pub const KEY: &'static str = "sys:sys_pwr_cmd";
    pub const ID: u32 = 0x113;
    pub const DLC: usize = 2;
    pub const CYCLE_MS: u32 = 100;
    pub const EXTENDED: bool = false;
    pub const LOW_ID: u32 = 0x113;
    pub const LOW_CYCLE_MS: u32 = 100;

    pub fn pack(&self, out: &mut [u8]) -> CodecStatus {
        if out.len() != Self::DLC { return CodecStatus::UnexpectedLength; }
        let mut payload = [0u8; 8];
        detail::insert(&mut payload, 0, 0, 8, false, (if self.power_state { 1u64 } else { 0u64 }));
        detail::insert(&mut payload, 1, 0, 8, false, (self.rolling_counter as u64));
        out.copy_from_slice(&payload[..Self::DLC]);
        CodecStatus::Ok
    }

    pub fn unpack(data: &[u8]) -> Result<Self, CodecStatus> {
        if data.len() != Self::DLC { return Err(CodecStatus::UnexpectedLength); }
        let mut value = Self { power_state: false, rolling_counter: 0 };
        let raw_power_state = detail::extract(data, 0, 0, 8, false);
        if raw_power_state > 1 { return Err(CodecStatus::ValueOutOfRange); }
        value.power_state = (raw_power_state != 0);
        let raw_rolling_counter = detail::extract(data, 1, 0, 8, false);
        value.rolling_counter = raw_rolling_counter as u8;
        Ok(value)
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SysSafetySts {
    pub estop_source: u8,
    pub node_presence: u8,
    pub estop_reason: u8,
    pub rolling_counter: u8,
    pub e2e_crc: u8,
}

impl SysSafetySts {
    pub const KEY: &'static str = "sys:sys_safety_sts";
    pub const ID: u32 = 0x11;
    pub const DLC: usize = 5;
    pub const CYCLE_MS: u32 = 200;
    pub const EXTENDED: bool = false;
    pub const HIGH_ID: u32 = 0x11;
    pub const HIGH_CYCLE_MS: u32 = 200;
    pub const LOW_ID: u32 = 0x11;
    pub const LOW_CYCLE_MS: u32 = 200;
    pub const ESTOPSOURCE_NONE: u8 = 0;
    pub const ESTOPSOURCE_LOCALSYS: u8 = 1;
    pub const ESTOPSOURCE_CAN001: u8 = 2;
    pub const ESTOPSOURCE_PEERFAULT: u8 = 3;
    pub const ESTOPREASON_NONE: u8 = 0;
    pub const ESTOPREASON_HWBUTTON: u8 = 1;
    pub const ESTOPREASON_RTHBLOST: u8 = 2;
    pub const ESTOPREASON_CAN001: u8 = 3;
    pub const ESTOPREASON_MTRFAULT: u8 = 4;
    pub const ESTOPREASON_EGASFAULT: u8 = 5;
    pub const ESTOPREASON_TASKDEADLINE: u8 = 6;
    pub const ESTOPREASON_CANBUSOFF: u8 = 7;

    pub fn pack(&self, out: &mut [u8]) -> CodecStatus {
        if out.len() != Self::DLC { return CodecStatus::UnexpectedLength; }
        if self.estop_source > 3 { return CodecStatus::ValueOutOfRange; }
        if self.estop_source != 0 && self.estop_source != 1 && self.estop_source != 2 && self.estop_source != 3 { return CodecStatus::InvalidEnum; }
        if self.node_presence > 63 { return CodecStatus::ValueOutOfRange; }
        if self.estop_reason > 7 { return CodecStatus::ValueOutOfRange; }
        if self.estop_reason != 0 && self.estop_reason != 1 && self.estop_reason != 2 && self.estop_reason != 3 && self.estop_reason != 4 && self.estop_reason != 5 && self.estop_reason != 6 && self.estop_reason != 7 { return CodecStatus::InvalidEnum; }
        let mut payload = [0u8; 8];
        detail::insert(&mut payload, 0, 0, 8, false, (self.estop_source as u64));
        detail::insert(&mut payload, 1, 0, 8, false, (self.node_presence as u64));
        detail::insert(&mut payload, 2, 0, 8, false, (self.estop_reason as u64));
        detail::insert(&mut payload, 3, 0, 8, false, (self.rolling_counter as u64));
        detail::insert(&mut payload, 4, 0, 8, false, (self.e2e_crc as u64));
        out.copy_from_slice(&payload[..Self::DLC]);
        CodecStatus::Ok
    }

    pub fn unpack(data: &[u8]) -> Result<Self, CodecStatus> {
        if data.len() != Self::DLC { return Err(CodecStatus::UnexpectedLength); }
        let mut value = Self { estop_source: 0, node_presence: 0, estop_reason: 0, rolling_counter: 0, e2e_crc: 0 };
        let raw_estop_source = detail::extract(data, 0, 0, 8, false);
        value.estop_source = raw_estop_source as u8;
        if value.estop_source > 3 { return Err(CodecStatus::ValueOutOfRange); }
        if value.estop_source != 0 && value.estop_source != 1 && value.estop_source != 2 && value.estop_source != 3 { return Err(CodecStatus::InvalidEnum); }
        let raw_node_presence = detail::extract(data, 1, 0, 8, false);
        value.node_presence = raw_node_presence as u8;
        if value.node_presence > 63 { return Err(CodecStatus::ValueOutOfRange); }
        let raw_estop_reason = detail::extract(data, 2, 0, 8, false);
        value.estop_reason = raw_estop_reason as u8;
        if value.estop_reason > 7 { return Err(CodecStatus::ValueOutOfRange); }
        if value.estop_reason != 0 && value.estop_reason != 1 && value.estop_reason != 2 && value.estop_reason != 3 && value.estop_reason != 4 && value.estop_reason != 5 && value.estop_reason != 6 && value.estop_reason != 7 { return Err(CodecStatus::InvalidEnum); }
        let raw_rolling_counter = detail::extract(data, 3, 0, 8, false);
        value.rolling_counter = raw_rolling_counter as u8;
        let raw_e2e_crc = detail::extract(data, 4, 0, 8, false);
        value.e2e_crc = raw_e2e_crc as u8;
        Ok(value)
    }
}


